	private static final class BoundedHashJoinIteration extends HashJoinIteration {
		private final long maxMaterializedRightRows;
		private Collection<?> materializationCache;

		private BoundedHashJoinIteration(QueryEvaluationStep left, QueryEvaluationStep right, BindingSet bindings,
				HashJoinBindingContract contract, QueryEvaluationContext context, LeftJoin leftJoin,
				long maxMaterializedRightRows) {
			super(left, right, bindings, true, contract, context, BuildSide.RIGHT, leftJoin);
			this.maxMaterializedRightRows = maxMaterializedRightRows;
		}

		@Override
		protected Collection<BindingSet> makeIterationCache(CloseableIteration<BindingSet> iter) {
			Collection<BindingSet> cache = super.makeIterationCache(iter);
			materializationCache = cache;
			return cache;
		}

		@Override
		protected <E> void add(Collection<E> collection, E value) throws QueryEvaluationException {
			if (collection == materializationCache && collection.size() >= maxMaterializedRightRows) {
				throw new MaterializationLimitExceededException();
			}
			super.add(collection, value);
		}
	}

